text:
{
  "title_novice": "Ложный водонефтяной контакт из-за фильтрата",
  "summary": [
    {"text": "В пластах, которые легко пропускают жидкость по вертикали (высокая вертикальная проницаемость), фильтрат может уйти вниз, под водонефтяной контакт.", "claims": ["c1", "c7"]},
    {"text": "Слой под контактом по сопротивлению похож на нефтяную часть, поэтому ВНК по электрике можно провести ниже истинного.", "claims": ["c3", "c4", "c5"]},
    {"text": "Чтобы не ошибиться, положение контакта проверяют радиометрией, записанной в обсаженной колонне скважины.", "claims": ["c6"]}
  ],
  "claims": [
    {"key": "c1", "text": "В пластах с высокой вертикальной проницаемостью у ВНК наблюдается перераспределение флюидов ниже контакта под действием тяжести.", "kind": "observation", "unit_id": "u-027-bb0c82", "page": 27, "quote": "В скважинах, вскрывающих коллекторы с высокой вертикальной проницаемостью, в зоне ВНК наблюдается гравитационное перераспределение флюидов ниже ВНК", "numbers": [], "question": null},
    {"key": "c2", "text": "Пресный фильтрат бурового раствора уходит из прежней зоны проникновения в слой коллектора под ВНК.", "kind": "observation", "unit_id": "u-028-8714a5", "page": 28, "quote": "раствора перемещается из первоначальной зоны проникновения в слой коллектора, подстилающий ВНК", "numbers": [], "question": null},
    {"key": "c3", "text": "По диаграммам сопротивлений слой под ВНК почти не отличается от нефтенасыщенной части коллектора.", "kind": "observation", "unit_id": "u-028-8714a5", "page": 28, "quote": "На диаграммах сопротивлений этот слой практически не отличается по величине ρ₀ от нефтенасыщенной части коллектора", "numbers": [], "question": null},
    {"key": "c4", "text": "Из-за этого электрические методы определяют положение ВНК неточно.", "kind": "inference", "unit_id": "u-028-8714a5", "page": 28, "quote": "что приводит к неточному определению ВНК по данным электрических методов", "numbers": [], "question": null},
    {"key": "c5", "text": "Без учёта этого явления метод сопротивлений может опустить ВНК на 1–1,5 м ниже истинного; оценка сделана ТатНИИ для Ромашкинского месторождения.", "kind": "observation", "unit_id": "u-028-8714a5", "page": 28, "quote": "Сотрудниками ТатНИИ показано, что для коллекторов основных продуктивных пластов Ромашкинского месторождения при исследовании методом сопротивлений без учета указанного явления можно понизить ВНК на 1 – 1,5 м по сравнению с истинным его положением", "numbers": ["1", "1,5"], "question": null},
    {"key": "c6", "text": "Радиометрия, записанная в колонне скважины, позволяет избежать этой ошибки.", "kind": "inference", "unit_id": "u-028-8714a5", "page": 28, "quote": "Анализ данных радиометрии, полученных в колонне скважины, позволяет избежать этой ошибки", "numbers": [], "question": null},
    {"key": "c7", "text": "Явление описано для коллекторов с высокой вертикальной проницаемостью.", "kind": "assumption", "unit_id": "u-027-bb0c82", "page": 27, "quote": "коллекторы с высокой вертикальной проницаемостью", "numbers": [], "question": null},
    {"key": "c8", "text": "Рисунок 33 показывает пример неправильного определения ВНК по электрометрии в терригенном коллекторе с высокой вертикальной проницаемостью.", "kind": "observation", "unit_id": "u-027-d64306", "page": 27, "quote": "Пример неправильного определения положения ВНК по данным электрометрии в терригенном коллекторе с высокой вертикальной проницаемостью", "numbers": [], "question": null},
    {"key": "c9", "text": "На рисунке 33 ложный ВНК отмечен отдельным обозначением (номер 5) в легенде.", "kind": "observation", "unit_id": "u-027-eb3d68", "page": 27, "quote": "1 – глина; песчаники; 2 – нефтеносные, 3 – водоносные; 4 – ВНК; 5 – ложный ВНК", "numbers": ["1", "2", "3", "4", "5"], "question": null}
  ],
  "mechanism": [
    {"text": "В коллекторе с высокой вертикальной проницаемостью фильтрат бурового раствора может уходить вниз.", "claims": ["c1", "c7"], "hypothesis": false},
    {"text": "Пресный фильтрат попадает в слой под ВНК из зоны проникновения, которая была рядом со стволом.", "claims": ["c2"], "hypothesis": false},
    {"text": "Сопротивление этого слоя близко к сопротивлению нефтенасыщенной части, поэтому по электрике его не отличить от нефти.", "claims": ["c3", "c4"], "hypothesis": false},
    {"text": "Граница, проведённая по сопротивлению, смещается вниз, и получается ложный ВНК.", "claims": ["c4", "c5", "c9"], "hypothesis": false},
    {"text": "Пресный фильтрат обычно плотнее нефти, поэтому он может опускаться сквозь неё.", "claims": [], "hypothesis": true},
    {"text": "Пресная жидкость плохо проводит ток, поэтому её сопротивление высокое, как у нефти; соль в пластовой воде снижает сопротивление.", "claims": [], "hypothesis": true}
  ],
  "practice": [
    {"text": "Если коллектор проницаемый по вертикали, не принимать граница по одной электрике за точный ВНК.", "claims": ["c1", "c7"], "hypothesis": false},
    {"text": "Проверить положение контакта радиометрией, записанной в обсаженной колонне.", "claims": ["c6"], "hypothesis": false},
    {"text": "Учитывать возможную ошибку около 1–1,5 м при электрическом определении ВНК без поправки.", "claims": ["c5"], "hypothesis": false},
    {"text": "Сопоставлять электрические кривые с результатами испытаний, если они есть.", "claims": [], "hypothesis": true}
  ],
  "nuances": [
    {"text": "Автор связывает явление с высокой вертикальной проницаемостью коллектора.", "claims": ["c7"], "hypothesis": false},
    {"text": "Величина смещения 1–1,5 м получена для основных продуктивных пластов Ромашкинского месторождения.", "claims": ["c5"], "hypothesis": false},
    {"text": "Для других пластов величина смещения в тексте не приведена.", "claims": [], "hypothesis": false},
    {"text": "Если проницаемость по вертикали низкая, из текста не следует, что ложный ВНК возникает; это условие автор не разбирает.", "claims": ["c7"], "hypothesis": true}
  ],
  "deeper": [
    {"title": "Почему вода опускается сквозь нефть", "text": "Нефть обычно легче воды, поэтому вода (в том числе пресный фильтрат) может опускаться вниз сквозь нефть под действием тяжести.", "claims": [], "hypothesis": true}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Условие явления: коллектор с высокой вертикальной проницаемостью.", "claims": ["c7"]},
    {"text": "Смещение ВНК при методе сопротивлений без учёта явления: на 1 – 1,5 м по сравнению с истинным положением.", "claims": ["c5"]},
    {"text": "Объект оценки: основные продуктивные пласты Ромашкинского месторождения.", "claims": ["c5"]},
    {"text": "Пример приведён для терригенного коллектора (рис. 33).", "claims": ["c8"]}
  ],
  "terms_defined": [
    {"term": "вертикальная проницаемость", "term_en": "vertical permeability", "abbr": "", "definition": "Способность пласта пропускать жидкость по вертикали, то есть сверху вниз и снизу вверх. Высокая вертикальная проницаемость позволяет фильтрату уходить вниз.", "claims": ["c1"]},
    {"term": "гравитационное перераспределение флюидов", "term_en": "gravity redistribution of fluids", "abbr": "", "definition": "Перемещение жидкостей под действием силы тяжести. В этом узле — уход пресного фильтрата вниз, в слой под ВНК.", "claims": ["c1", "c2"]},
    {"term": "ложный ВНК", "term_en": "false water-oil contact", "abbr": "", "definition": "Граница, которую по электрическим данным принимают за водонефтяной контакт, но которая лежит ниже истинного ВНК из-за слоя с фильтратом.", "claims": ["c9", "c5"]},
    {"term": "радиометрия в колонне", "term_en": "radiometry in cased hole", "abbr": "", "definition": "Измерения радиоактивности пород, записанные в обсаженной колонной скважине. Автор использует их, чтобы уточнить ВНК.", "claims": ["c6"]}
  ],
  "terms_used": ["ВНК (водонефтяной контакт)", "фильтрат бурового раствора", "зона проникновения", "коллектор", "нефтенасыщенная часть коллектора", "удельное электрическое сопротивление", "обсаженная скважина", "пресный буровой раствор", "электрические методы"],
  "formulas": [],
  "tables": [],
  "figures": [
    {"label": "Рис. 33", "unit_id": "u-027-d64306", "role": "Пример неправильного определения ВНК по электрометрии; легенда содержит обозначение ложного ВНК (5).", "redraw": true}
  ],
