  "typos": [
    {"unit_id": "u-028-8714a5", "original": "ρ₀", "corrected": "ρп (вероятно)", "note": "В той же главе сопротивление нефтенасыщенной части обозначено ρп. Символ может быть искажён распознаванием; по смыслу речь о сопротивлении.", "confidence": "medium", "needs_scan_check": true},
    {"unit_id": "u-027-b44a20", "original": "машинное описание: интервал 2060–2090 м, НГМ 27/XII-1986 г., ВНК у 2085–2090 м", "corrected": "сверить со сканом: описание не соответствует подписи Рис. 33 (ложный ВНК, терригенный коллектор)", "note": "Машинное описание привязано к Рис. 33, но описывает другой планшет. Из него цитаты не взяты.", "confidence": "low", "needs_scan_check": true}
  ],
